"""Product-level single-slot compute lock (ASR / LLM / Pro handoff).

Distinct from TRANSUB_MAX_CONCURRENT_JOBS (engine job scheduler). Desktop and
Factory clients acquire this lock so multi-window / multi-client work shares one
GPU owner — see compute-ownership P3.
"""
from __future__ import annotations

import threading
import time
import uuid
from typing import Any

_KIND_LABELS = {
    "engine_batch": "引擎字幕任务",
    "engine_range": "引擎区间重转写",
    "engine_resume": "引擎从原文继续",
    "engine_opus_text": "文本翻译",
    "twai_batch": "字幕生成任务",
    "twai_range": "区间重转写",
    "twai_trial": "参数对比试跑",
    "advanced_reconstruct": "语境重构",
    "advanced_film_reconstruct": "影片理解重构",
    "advanced_smart_translate": "智能翻译",
    "advanced_semantic_review": "双语语义审阅",
    "advanced_batch_reconstruct": "批量语境重构",
    "advanced_asr_semantic_repair": "转录语义校正",
    "sakura_translate": "推理翻译",
    "managed_llm_perf": "模型性能测试",
    "compute": "计算任务",
}


def kind_label(kind: str) -> str:
    k = str(kind or "").strip()
    return _KIND_LABELS.get(k) or (k or "计算任务")


class ProductComputeLock:
    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._holder: dict[str, Any] | None = None

    def status(self) -> dict[str, Any]:
        with self._lock:
            if not self._holder:
                return {"ok": True, "busy": False, "via": "engine"}
            h = dict(self._holder)
        return {
            "ok": True,
            "busy": True,
            "kind": h.get("kind"),
            "owner": h.get("owner"),
            "source": h.get("source"),
            "clientId": h.get("clientId"),
            "since": h.get("since"),
            "label": kind_label(str(h.get("kind") or "")),
            "via": "engine",
        }

    def acquire(
        self,
        *,
        kind: str = "compute",
        owner: str = "",
        source: str = "",
        client_id: str = "",
    ) -> dict[str, Any]:
        with self._lock:
            if self._holder:
                h = dict(self._holder)
                label = kind_label(str(h.get("kind") or ""))
                owner_s = str(h.get("owner") or "").strip()
                owner_bit = f"（{owner_s}）" if owner_s else ""
                return {
                    "ok": False,
                    "error": f"已有{label}正在运行{owner_bit}，请等待完成后再试",
                    "code": "compute_busy",
                    "holder": {
                        "kind": h.get("kind"),
                        "owner": h.get("owner"),
                        "source": h.get("source"),
                        "clientId": h.get("clientId"),
                        "since": h.get("since"),
                        "label": label,
                    },
                    "via": "engine",
                }
            token = str(uuid.uuid4())
            self._holder = {
                "token": token,
                "kind": str(kind or "compute").strip() or "compute",
                "owner": str(owner or "").strip(),
                "source": str(source or "").strip(),
                "clientId": str(client_id or "").strip(),
                "since": int(time.time() * 1000),
            }
            h = dict(self._holder)
        return {
            "ok": True,
            "token": token,
            "kind": h["kind"],
            "owner": h["owner"],
            "source": h["source"],
            "clientId": h["clientId"],
            "since": h["since"],
            "label": kind_label(h["kind"]),
            "via": "engine",
        }

    def release(self, token: str = "") -> dict[str, Any]:
        with self._lock:
            if not self._holder:
                return {"ok": True, "released": False, "via": "engine"}
            if token and self._holder.get("token") != token:
                return {
                    "ok": False,
                    "error": "token mismatch",
                    "code": "token_mismatch",
                    "via": "engine",
                }
            self._holder = None
        return {"ok": True, "released": True, "via": "engine"}

    def force_release(self) -> dict[str, Any]:
        with self._lock:
            had = self._holder is not None
            self._holder = None
        return {"ok": True, "released": had, "via": "engine"}


LOCK = ProductComputeLock()
